    static float ParkDistance(ProtectedPark p,float x,float z)=>Mathf.Max(Mathf.Max(p.xMin-x,x-p.xMax),Mathf.Max(p.zMin-z,z-p.zMax));
    static ParkPaintChange[] PaintParkGrass(TownRoadPlan plan,Terrain[] lands){var changes=new List<ParkPaintChange>();foreach(var land in lands){var data=land.terrainData;var pos=land.transform.position;var bounds=new Rect(pos.x,pos.z,data.size.x,data.size.z);var extended=Rect.MinMaxRect(plan.park.xMin-2,plan.park.zMin-2,plan.park.xMax+2,plan.park.zMax+2);if(!bounds.Overlaps(extended))continue;int layer=Array.FindIndex(data.terrainLayers,t=>t&&t.name=="SWS_Grass");if(layer<0)throw new Exception("Original green grass layer missing");var h=DataHeightHash(data);var holes=DataHoleHash(data);var before=data.GetAlphamaps(0,0,data.alphamapWidth,data.alphamapHeight);var alpha=(float[,,])before.Clone();var row=new ParkPaintChange{terrain=P(land.transform),source=AssetDatabase.GetAssetPath(data),grassLayer=layer,heightsUnchanged=true,holesUnchanged=true,outsideFeatherUnchanged=true,insideParkAllGrass=true};row.output=roadOutput+"/Terrain/"+data.name+"_ParkGrass.asset";AssetDatabase.CopyAsset(row.source,row.output);var output=AssetDatabase.LoadAssetAtPath<TerrainData>(row.output);int w=data.alphamapWidth,height=data.alphamapHeight,n=data.alphamapLayers;for(int z=0;z<height;z++)for(int x=0;x<w;x++){float wx=pos.x+(x+.5f)*data.size.x/w,wz=pos.z+(z+.5f)*data.size.z/height;float distance=ParkDistance(plan.park,wx,wz);if(distance>=2)continue;float weight=distance<=0?1:1-Mathf.SmoothStep(0,1,distance/2);if(distance<=0)row.insideParkTexels++;bool changed=false;for(int k=0;k<n;k++){float value=Mathf.Lerp(before[z,x,k],k==layer?1:0,weight);if(value!=alpha[z,x,k])changed=true;alpha[z,x,k]=value;}if(changed)row.changedTexels++;}output.SetAlphamaps(0,0,alpha);land.terrainData=output;land.GetComponent<TerrainCollider>().terrainData=output;land.Flush();EditorUtility.SetDirty(output);var after=output.GetAlphamaps(0,0,w,height);for(int z=0;z<height;z++)for(int x=0;x<w;x++){float distance=ParkDistance(plan.park,pos.x+(x+.5f)*data.size.x/w,pos.z+(z+.5f)*data.size.z/height);if(distance>=2)for(int k=0;k<n;k++)if(Mathf.Abs(after[z,x,k]-before[z,x,k])>1e-6f)row.outsideFeatherUnchanged=false;if(distance<=0&&after[z,x,layer]<.9999f)row.insideParkAllGrass=false;}row.heightsUnchanged=DataHeightHash(output)==h;row.holesUnchanged=DataHoleHash(output)==holes;if(!row.heightsUnchanged||!row.holesUnchanged||!row.outsideFeatherUnchanged||!row.insideParkAllGrass)throw new Exception("Park paint boundaries failed");changes.Add(row);}return changes.ToArray();}
    static void FlatRoadPrototype(Material asphalt,Material sidewalk,Material curb,Material white){var root=new GameObject("TwoLaneRoad_20m_8mCarriageway");var r=root.transform;var g=new RoadGeometry();g.Strip(new Vector3(0,0,-10),new Vector3(0,0,10),8,0,(x,z)=>0);RoadMesh(r,"ModuleRoad20_Asphalt",g,asphalt,true);var walk=new RoadGeometry();var edge=new RoadGeometry();foreach(float sign in new[]{-1f,1f}){walk.Strip(new Vector3(0,0,-10),new Vector3(0,0,10),2.4f,sign*5.4f,(x,z)=>.18f);edge.Strip(new Vector3(0,0,-10),new Vector3(0,0,10),.2f,sign*4.1f,(x,z)=>.2f);}RoadMesh(r,"ModuleRoad20_Sidewalks",walk,sidewalk,true);RoadMesh(r,"ModuleRoad20_Curbs",edge,curb,true);var lines=new RoadGeometry();for(float z=-8;z<=8;z+=4)lines.Strip(new Vector3(0,0,z-1),new Vector3(0,0,z+1),.18f,0,(x,y)=>.015f);RoadMesh(r,"ModuleRoad20_WhiteDashes",lines,white,false,false);PrefabUtility.SaveAsPrefabAsset(root,roadOutput+"/Prefabs/TwoLaneRoad_20m.prefab");UnityEngine.Object.DestroyImmediate(root);}
    public static void BuildTownRoads(){if(File.Exists(Path.Combine(Reports,"town-road-build.json")))throw new Exception("New road town already saved; inspect receipt before replay");if(!File.Exists(Path.Combine(Reports,"town-road-planning-backup.json")))throw new Exception("Current-task backup required");var inventory=JsonUtility.FromJson<PlanningInventory>(File.ReadAllText(Path.Combine(Reports,"town-road-planning-inventory.json")));var plan=RoadPlan();if(inventory.failures.Length>0||JsonUtility.ToJson(inventory.plan)!=JsonUtility.ToJson(plan))throw new Exception("Validated plan must match the build input");
        RoadProgress("LOAD_AND_PROTECT");var scenes=LoadIsland();var game=scenes[0];var all=scenes.SelectMany(All).ToArray();IndexRevisionObjects(all);foreach(var p in inventory.protectedNodes){var t=Resolve<Transform>(p.globalId);if(!t||Signature(t)!=p.signature)throw new Exception("Protected node changed before build: "+p.path);}if(all.Any(t=>t.name=="TownRoadNetwork20261019"))throw new Exception("Road root already exists");var lands=all.Where(t=>t.gameObject.activeInHierarchy).Select(t=>t.GetComponent<Terrain>()).Where(t=>t).ToArray();
        roadOutput=RoadLibrary+"/Generated/"+DateTime.UtcNow.ToString("yyyyMMdd_HHmmss");foreach(var folder in new[]{"Meshes","Materials","Prefabs","Terrain"})Directory.CreateDirectory(roadOutput+"/"+folder);AssetDatabase.Refresh();roadMeshCount=0;builtCrosswalks=builtSignals=builtBins=builtPoles=0;PrepareDeck(plan,lands);
        var asphalt=AssetDatabase.LoadAssetAtPath<Material>("Assets/Material/M_asphalt_01 1.mat");var sidewalk=AssetDatabase.LoadAssetAtPath<Material>("Assets/Material/M_tiles_ground.mat");var curb=AssetDatabase.LoadAssetAtPath<Material>("Assets/Material/M_curbstone_2.mat");var yellow=AssetDatabase.LoadAssetAtPath<Material>("Assets/SushiAndFish/Modules/OriginalIsland/FootprintMarkers/SoftYellowDashes.mat");var cable=AssetDatabase.LoadAssetAtPath<Material>("Assets/Material/M_cables_dark.mat");if(!asphalt||!sidewalk||!curb||!yellow||!cable)throw new Exception("Original material dependency missing");
        var white=RoadColor("RoadMarkingWhite",new Color(.96f,.95f,.89f));var foundation=RoadColor("RoadbedConcrete",new Color(.42f,.44f,.42f));foundation.SetFloat("_Cull",0);var dark=RoadColor("SignalHousing",new Color(.055f,.064f,.067f));var red=RoadColor("SignalRed",new Color(.88f,.055f,.025f));var amber=RoadColor("SignalAmber",new Color(1,.58f,.035f));var green=RoadColor("SignalGreen",new Color(.045f,.78f,.2f));
        var root=new GameObject("TownRoadNetwork20261019");SceneManager.MoveGameObjectToScene(root,game);var roads=RoadGroup(root.transform,"RoadSections",Vector3.zero);var junctions=RoadGroup(root.transform,"Junctions",Vector3.zero);var props=RoadGroup(root.transform,"StreetFurniture",Vector3.zero);var parcels=RoadGroup(root.transform,"YellowParcelReservations",Vector3.zero);var nodes=RoadNodes(plan);RoadProgress("BUILD_ROAD_SURFACES");foreach(var road in plan.roads)BuildRoadLine(roads,road,plan,asphalt,sidewalk,curb,white,foundation,nodes);
        RoadProgress("BUILD_JUNCTIONS_AND_MARKINGS");foreach(var node in nodes){var arms=RoadArms(node,plan);if(arms.Length<2||arms.Length==2&&Vector2.Dot(arms[0],arms[1])<-.9f)continue;RoadCorners(junctions,node,plan,sidewalk,curb);RoadCrosswalks(junctions,node,plan,white);}foreach(var turn in plan.turnarounds)TurnPad(junctions,turn,asphalt,sidewalk,curb,foundation);
        RoadProgress("BUILD_SIGNALS_BINS_POLES_AND_PARCELS");foreach(var point in plan.signalJunctions)JunctionProps(props,point,plan,dark,red,amber,green);PowerPoles(props,cable);foreach(var plot in plan.plots)ParcelOutline(parcels,plot,yellow);FlatRoadPrototype(asphalt,sidewalk,curb,white);
        foreach(Transform section in roads)PrefabUtility.SaveAsPrefabAsset(section.gameObject,roadOutput+"/Prefabs/"+section.name+".prefab");var sampleSignal=props.GetChild(0);PrefabUtility.SaveAsPrefabAsset(sampleSignal.gameObject,roadOutput+"/Prefabs/SignalJunction_Reference.prefab");
        RoadProgress("PAINT_PARK_GRASS_WITHOUT_HEIGHT_CHANGES");var painted=PaintParkGrass(plan,lands);var old=JsonUtility.FromJson<TownPlan>(File.ReadAllText(Path.Combine(Reports,"town-module-export.json")));int removed=0;foreach(var row in old.objects.Where(x=>x.action=="KEEP_MAIN_ROAD")){var t=Resolve<Transform>(row.id);if(!t)throw new Exception("Old road instance missing before replacement");UnityEngine.Object.DestroyImmediate(t.gameObject);removed++;}
        var failures=inventory.protectedNodes.Where(p=>{var t=Resolve<Transform>(p.globalId);return !t||Signature(t)!=p.signature;}).Select(p=>p.path).ToArray();bool heights=true,holes=true;foreach(var baseline in inventory.terrains){var land=lands.Single(t=>P(t.transform)==baseline.path);heights&=DataHeightHash(land.terrainData)==baseline.heightHash;holes&=DataHoleHash(land.terrainData)==baseline.holeHash;}
        if(failures.Length>0||!heights||!holes||builtBins!=8||builtPoles!=6||plan.plots.Length!=13)throw new Exception("Road town preservation invariant failed");RoadProgress("SAVE_AND_REOPEN");foreach(var scene in scenes)EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();var result=new TownRoadBuildResult{utc=DateTime.UtcNow.ToString("o"),stage="SAVED_NEEDS_REOPEN_AND_RUNTIME_VERIFICATION",assets=roadOutput,roadSections=plan.roads.Length,parcels=plan.plots.Length,crosswalks=builtCrosswalks,signalPosts=builtSignals,signalJunctions=plan.signalJunctions.Length,bins=builtBins,powerPoles=builtPoles,replacedRoadRoots=removed,meshes=roadMeshCount,prefabs=Directory.GetFiles(roadOutput+"/Prefabs","*.prefab").Length,protectedNodes=inventory.protectedNodes.Length,centrelineMetres=plan.roads.Sum(r=>Vector3.Distance(r.a.Vector,r.b.Vector)),terrainHeightsUnchanged=heights,terrainHolesUnchanged=holes,protectedNodesUnchanged=true,parkPaint=painted,protectionFailures=failures,plan=plan};File.WriteAllText(Path.Combine(Reports,"town-road-build.json"),JsonUtility.ToJson(result,true));revisionObjects=null;revisionIds=null;RebuildRevisionNavigation();result.navigation=JsonUtility.FromJson<NavigationReceipt>(File.ReadAllText(Path.Combine(Reports,"island-revision-final-navigation.json"))).asset;File.WriteAllText(Path.Combine(Reports,"town-road-build.json"),JsonUtility.ToJson(result,true));IslandFrontEndBuilder.RefreshMenuPresentation();EditorSceneManager.OpenScene("Assets/Scenes/Main.unity");RoadProgress("SAVED "+result.roadSections+" roads / "+result.parcels+" parcels");
